struct RTTR_AUTO_REGISTER_CLASS Color {
  uint8_t red, green, blue;  // in the range [0 - 255]
};

struct RTTR_AUTO_REGISTER_CLASS TimeRange {
  Frame start;
  Frame end;

  Frame duration() const {
    return end - start + 1;
  }

  bool isValid() const {
    return 0 <= start && start <= end;
  }

  bool contains(Frame frame) const {
    return start <= frame && frame <= end;
  }
};

struct PAG_API Point {
  float x;
  float y;
  static const Point& Zero() {
    static const Point zero = Point::Make(0, 0);
    return zero;
  }
  static constexpr Point Make(float x, float y) { return {x, y}; }
  static constexpr Point Make(int x, int y) { return {static_cast<float>(x), static_cast<float>(y)}; }
  bool isZero() const { return (0 == x) & (0 == y); }
  void set(float xValue, float yValue) { x = xValue; y = yValue; }
  void offset(float dx, float dy) { x += dx; y += dy; }
  float length() const { return Point::Length(x, y); }
  friend bool operator==(const Point& a, const Point& b) { return a.x == b.x && a.y == b.y; }
  friend bool operator!=(const Point& a, const Point& b) { return a.x != b.x || a.y != b.y; }
  friend Point operator-(const Point& a, const Point& b) { return {a.x - b.x, a.y - b.y}; }
  friend Point operator+(const Point& a, const Point& b) { return {a.x + b.x, a.y + b.y}; }
  static float Length(float x, float y) { return sqrt(x * x + y * y); }
  static float Distance(const Point& a, const Point& b) { return Length(a.x - b.x, a.y - b.y); }
};

struct PAG_API Point3D {
  float x;
  float y;
  float z;
  static const Point3D& Zero() { static const Point3D zero = Point3D::Make(0, 0, 0); return zero; }
  static constexpr Point3D Make(float x, float y, float z) { return {x, y, z}; }
  bool isZero() const { return (0 == x) & (0 == y) & (0 == z); }
  void set(float xValue, float yValue, float zValue) { x = xValue; y = yValue; z = zValue; }
  void offset(float dx, float dy, float dz) { x += dx; y += dy; z += dz; }
  float length() const { return Point3D::Length(x, y, z); }
  friend bool operator==(const Point3D& a, const Point3D& b) { return a.x == b.x && a.y == b.y && a.z == b.z; }
  friend bool operator!=(const Point3D& a, const Point3D& b) { return a.x != b.x || a.y != b.y || a.z != b.z; }
  friend Point3D operator-(const Point3D& a, const Point3D& b) { return {a.x - b.x, a.y - b.y, a.z - b.z}; }
  friend Point3D operator+(const Point3D& a, const Point3D& b) { return {a.x + b.x, a.y + b.y, a.z + b.z}; }
  static float Length(float x, float y, float z) { return sqrt(x * x + y * y + z * z); }
  static float Distance(const Point3D& a, const Point3D& b) { return Length(a.x - b.x, a.y - b.y, a.z - b.z); }
};

struct PAG_API Rect {
  float left;
  float top;
  float right;
  float bottom;
  static constexpr Rect MakeEmpty() { return {0, 0, 0, 0}; }
  static constexpr Rect MakeWH(float w, float h) { return {0, 0, w, h}; }
  static constexpr Rect MakeWH(int w, int h) { return {0, 0, static_cast<float>(w), static_cast<float>(h)}; }
  static constexpr Rect MakeLTRB(float l, float t, float r, float b) { return {l, t, r, b}; }
  static constexpr Rect MakeXYWH(float x, float y, float w, float h) { return {x, y, x + w, y + h}; }
  bool isEmpty() const { return !(left < right && top < bottom); }
  bool isSorted() const { return left <= right && top <= bottom; }
  float x() const { return left; }
  float y() const { return top; }
  float width() const { return right - left; }
  float height() const { return bottom - top; }
  float centerX() const { return left * 0.5f + right * 0.5f; }
  float centerY() const { return top * 0.5f + bottom * 0.5f; }
  friend bool operator==(const Rect& a, const Rect& b) { return a.left == b.left && a.right == b.right && a.top == b.top && a.bottom == b.bottom; }
  friend bool operator!=(const Rect& a, const Rect& b) { return a.left != b.left || a.right != b.right || a.top != b.top || a.bottom != b.bottom; }
  void setEmpty() { *this = MakeEmpty(); }
  void setLTRB(float l, float t, float r, float b) { left = l; top = t; right = r; bottom = b; }
  bool setBounds(const Point pts[], int count);
  void setXYWH(float x, float y, float width, float height) { left = x; top = y; right = x + width; bottom = y + height; }
  void setWH(float width, float height) { left = 0; top = 0; right = width; bottom = height; }
  Rect makeOffset(float dx, float dy) const { return MakeLTRB(left + dx, top + dy, right + dx, bottom + dy); }
  Rect makeInset(float dx, float dy) const { return MakeLTRB(left + dx, top + dy, right - dx, bottom - dy); }
  Rect makeOutset(float dx, float dy) const { return MakeLTRB(left - dx, top - dy, right + dx, bottom + dy); }
  void offset(float dx, float dy) { left += dx; top += dy; right += dx; bottom += dy; }
  void offset(const Point& delta) { this->offset(delta.x, delta.y); }
  void offsetTo(float newX, float newY) { right += newX - left; bottom += newY - top; left = newX; top = newY; }
  void inset(float dx, float dy) { left += dx; top += dy; right -= dx; bottom -= dy; }
  void outset(float dx, float dy) { this->inset(-dx, -dy); }
  void scale(float scaleX, float scaleY);
  bool intersect(const Rect& r) { return this->intersect(r.left, r.top, r.right, r.bottom); }
  bool intersect(float l, float t, float r, float b);
  bool intersect(const Rect& a, const Rect& b);
  bool intersects(float l, float t, float r, float b) const;
  bool intersects(const Rect& r) const;
  static bool Intersects(const Rect& a, const Rect& b);
  void join(float l, float t, float r, float b);
  void join(const Rect& r) { this->join(r.left, r.top, r.right, r.bottom); }
  bool contains(float x, float y) const { return x >= left && x < right && y >= top && y < bottom; }
  bool contains(const Rect& r) const { return left <= r.left && top <= r.top && right >= r.right && bottom >= r.bottom; }
  void roundOut();
  void round();
  void sort();
  Rect makeSorted() const;
};

class PAG_API Matrix {
 public:
  static Matrix MakeScale(float sx, float sy) { Matrix m = {}; m.setScale(sx, sy); return m; }
  static Matrix MakeScale(float scale) { Matrix m = {}; m.setScale(scale, scale); return m; }
  static Matrix MakeTrans(float dx, float dy) { Matrix m = {}; m.setTranslate(dx, dy); return m; }
  static Matrix MakeAll(float scaleX, float skewX, float transX, float skewY, float scaleY,
                        float transY, float pers0, float pers1, float pers2) { Matrix m = {}; m.setAll(scaleX, skewX, transX, skewY, scaleY, transY, pers0, pers1, pers2); return m; }
  bool isIdentity() const;
  float operator[](int index) const;
  float get(int index) const;
  float getScaleX() const { return values[SCALE_X]; }
  float getScaleY() const { return values[SCALE_Y]; }
  float getSkewY() const { return values[SKEW_Y]; }
  float getSkewX() const { return values[SKEW_X]; }
  float getTranslateX() const { return values[TRANS_X]; }
  float getTranslateY() const { return values[TRANS_Y]; }
  float& operator[](int index);
  void set(int index, float value);
  void setScaleX(float v);
  void setScaleY(float v);
  void setSkewY(float v);
  void setSkewX(float v);
  void setTranslateX(float v);
  void setTranslateY(float v);
  void setAll(float scaleX, float skewX, float transX, float skewY, float scaleY, float transY,
              float persp0, float persp1, float persp2);
  void setAffine(float a, float b, float c, float d, float tx, float ty);
  void get9(float buffer[9]) const;
  void set9(const float buffer[9]);
  void reset();
  void setIdentity() { this->reset(); }
  void setTranslate(float dx, float dy);
  void setScale(float sx, float sy, float px, float py);
  void setScale(float sx, float sy);
  void setRotate(float degrees, float px, float py);
  void setRotate(float degrees);
  void setSinCos(float sinV, float cosV, float px, float py);
  void setSinCos(float sinV, float cosV);
  void setSkew(float kx, float ky, float px, float py);
  void setSkew(float kx, float ky);
  void setConcat(const Matrix& a, const Matrix& b);
  void preTranslate(float dx, float dy);
  void preScale(float sx, float sy, float px, float py);
  void preScale(float sx, float sy);
  void preRotate(float degrees, float px, float py);
  void preRotate(float degrees);
  void preSkew(float kx, float ky, float px, float py);
  void preSkew(float kx, float ky);
  void preConcat(const Matrix& other);
  void postTranslate(float dx, float dy);
  void postScale(float sx, float sy, float px, float py);
  void postScale(float sx, float sy);
  void postRotate(float degrees, float px, float py);
  void postRotate(float degrees);
  void postSkew(float kx, float ky, float px, float py);
  void postSkew(float kx, float ky);
  void postConcat(const Matrix& other);
  bool invert(Matrix* inverse) const;
  bool invertible() const;
  void mapPoints(Point dst[], const Point src[], int count) const;
  void mapPoints(Point pts[], int count) const { this->mapPoints(pts, pts, count); }
  void mapXY(float x, float y, Point* result) const;
  Point mapXY(float x, float y) const { Point result = {}; this->mapXY(x, y, &result); return result; }
  void mapRect(Rect* dst, const Rect& src) const;
  void mapRect(Rect* rect) const { mapRect(rect, *rect); }
  Rect mapRect(const Rect& src) const { Rect dst = {}; mapRect(&dst, src); return dst; }
  friend PAG_API bool operator==(const Matrix& a, const Matrix& b);
  friend bool operator!=(const Matrix& a, const Matrix& b) { return !(a == b); }
  float getMinScale() const;
  float getMaxScale() const;
  bool isFinite() const;
  static const Matrix& I();
  static const Matrix& Invalid();
 private:
#pragma clang diagnostic push
#pragma clang diagnostic ignored "-Wunused-private-field"
  float values[6];
  mutable int32_t typeMask;
  static constexpr int SCALE_X = 0;
  static constexpr int SKEW_X = 1;
  static constexpr int TRANS_X = 2;
  static constexpr int SKEW_Y = 3;
  static constexpr int SCALE_Y = 4;
  static constexpr int TRANS_Y = 5;
#pragma clang diagnostic pop
};

