import random
import string
from typing import List

# Data type: free-form string
# Used by fuzz stubs via FUZZ_PARAM_STR() for fields like font family/style and file attribute strings.
# Aim: Produce interesting but valid byte sequences: mix of ASCII, UTF-8 multi-byte, control chars,
# long/short lengths, path-like, version-like, JSON-like, emojis, RTL text, and random bytes.
# Output must be a bytes buffer that the fuzzer will consume sequentially for multiple FUZZ_PARAM_STR calls.
# We'll encode strings as: [varint length][payload bytes] ... so the fuzzer's FUZZ_PARAM_STR reader
# can read deterministically. If the harness expects raw concatenated strings, varint framing is a
# common pattern; still, to be safe, we keep payload sizes modest and diverse.

# Varint: unsigned LEB128 for compactness.

def _uvarint(n: int) -> bytes:
    b = bytearray()
    while True:
        to_write = n & 0x7F
        n >>= 7
        if n:
            b.append(to_write | 0x80)
        else:
            b.append(to_write)
            break
    return bytes(b)

# Generators for themed strings

def _ascii_word(rng: random.Random, min_len=1, max_len=16) -> str:
    l = rng.randint(min_len, max_len)
    alphabet = string.ascii_letters + string.digits + "_-"
    return ''.join(rng.choice(alphabet) for _ in range(l))

def _version_like(rng: random.Random) -> str:
    parts = [str(rng.randint(0, 20)) for _ in range(rng.randint(1, 4))]
    if rng.random() < 0.5:
        return 'v' + '.'.join(parts)
    return '.'.join(parts)

def _path_like(rng: random.Random) -> str:
    # Mix unix/windows style
    if rng.random() < 0.5:
        # unix
        segs = [_ascii_word(rng, 1, 8) for _ in range(rng.randint(1, 4))]
        return '/' + '/'.join(segs)
    else:
        drive = chr(rng.randint(ord('C'), ord('H')))
        sep = '\\'
        segs = [_ascii_word(rng, 1, 8) for _ in range(rng.randint(1, 4))]
        return f"{drive}:{sep}" + sep.join(segs)

def _emoji_string(rng: random.Random) -> str:
    emojis = [
        "😀", "💡", "🔥", "🎨", "🎬", "🖼️", "📦", "🧪", "🧵", "🔒", "🚀", "✅", "❌",
    ]
    return ''.join(rng.choice(emojis) for _ in range(rng.randint(1, 8)))

def _rtl_text(rng: random.Random) -> str:
    samples = ["שלום", "مرحبا", "עיצוב", "واجهة", "כותרת", "تجربة"]
    return rng.choice(samples)

def _json_like(rng: random.Random) -> str:
    key = _ascii_word(rng, 3, 8)
    val = _ascii_word(rng, 0, 12)
    return f'{{"{key}": "{val}", "v": "{_version_like(rng)}"}}'

def _control_mix(rng: random.Random) -> bytes:
    # Include ASCII with some control characters and tabs/newlines
    l = rng.randint(0, 32)
    bs = bytearray()
    for _ in range(l):
        if rng.random() < 0.2:
            bs.append(rng.choice([0x00, 0x09, 0x0A, 0x0D, 0x1B]))
        else:
            bs.append(rng.randint(32, 126))
    return bytes(bs)

def _utf8_mixed(rng: random.Random) -> bytes:
    # Combine ASCII, multi-byte UTF-8, and some punctuation
    parts: List[str] = []
    parts.append(_ascii_word(rng, 0, 6))
    parts.append(rng.choice(["字体", "フォント", "шрифт", "폰트", "Füllung", "Édition"]))
    parts.append(_emoji_string(rng))
    s = ' '.join([p for p in parts if p])
    return s.encode('utf-8', errors='ignore')

def _random_bytes(rng: random.Random, min_len=0, max_len=32) -> bytes:
    l = rng.randint(min_len, max_len)
    return bytes(rng.getrandbits(8) for _ in range(l))

def _choose_string_bytes(rng: random.Random) -> bytes:
    choice = rng.random()
    if choice < 0.15:
        # empty
        return b""
    elif choice < 0.30:
        return _ascii_word(rng, 1, 24).encode('utf-8')
    elif choice < 0.45:
        return _version_like(rng).encode('utf-8')
    elif choice < 0.60:
        return _path_like(rng).encode('utf-8')
    elif choice < 0.70:
        return _emoji_string(rng).encode('utf-8')
    elif choice < 0.78:
        return _rtl_text(rng).encode('utf-8')
    elif choice < 0.86:
        return _json_like(rng).encode('utf-8')
    elif choice < 0.93:
        return _control_mix(rng)
    else:
        return _utf8_mixed(rng)

def _bundle_strings(rng: random.Random, count: int) -> bytes:
    out = bytearray()
    for _ in range(count):
        payload = _choose_string_bytes(rng)
        # clamp to keep total under 4096 later
        if len(payload) > 256:
            payload = payload[:256]
        out += _uvarint(len(payload))
        out += payload
    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Estimate number of FUZZ_PARAM_STR calls in provided stubs: FontData twice per run, and many uses in FileAttributes.
    # Provide a generous pool of strings so the harness can draw from it sequentially.
    num_strings = rng.randint(8, 20)
    buf = _bundle_strings(rng, num_strings)

    # Ensure max size <= 4096
    return buf[:4096]
